// Editorial proposal presentation; project data and generation stay in the workspace.
const routes=[
 {role:'建立生活方式共鸣',thesis:'地点会变，属于自己的日常不变。',reason:'把便携转译成仪式的延续，让产品出现在真实生活里，而不仅是功能演示中。',strength:'适合讲述使用场景，让消费者想象产品进入自己的生活。',tradeoff:'场景容易分散注意力，需要搭配清晰的产品细节。',layout:'温暖叙事 · 衬线标题 · 舒展留白',note:'用自然光与环境肌理建立亲近感，让产品成为生活的一部分。'},
 {role:'突出产品设计价值',thesis:'让每一个细节，都成为选择的理由。',reason:'将注意力集中到轮廓、材质与使用细节，通过有秩序的视觉表达建立品质感。',strength:'适合新品介绍和产品页，突出设计与细节的价值。',tradeoff:'表达偏冷静，需补充使用场景才能说透便携优势。',layout:'克制秩序 · 细字重 · 精准对齐',note:'用中性背景与侧向光线突出轮廓，让材质与结构自己说话。'},
 {role:'建立鲜明视觉记忆',thesis:'给习以为常的生活，一个出走的理由。',reason:'用反差色彩与更有张力的构图表达探索欲，让品牌成为打破日常的邀请。',strength:'适合社交传播和主题活动，快速建立鲜明的视觉印象。',tradeoff:'色彩与场景较强，需要保持产品识别，避免喧宾夺主。',layout:'大胆表达 · 粗体标题 · 色块碰撞',note:'用蓝与橙的对比建立节奏，保留明确的产品主体。'}
];
export function proposalMeta(i){return routes[i%routes.length]}
export function proposalCover(d,i,p,esc){const r=proposalMeta(i);return `<div class="proposal-cover"><img src="${esc(d.image)}" alt="${esc(d.name)}视觉方向"><span>${esc(r.role)}</span></div><div class="node-body proposal-summary"><h2>${esc(d.name)}</h2><p>${esc(r.thesis)}</p><div class="proposal-palette">${(d.palette||[]).map(c=>/^#[0-9a-f]{3,8}$/i.test(c)?`<i style="background:${c}"></i>`:'').join('')}<span>${esc((d.mood||[]).join(' · '))}</span></div><button data-proposal="${esc(d.id)}">查看完整提案 ↗</button>${p.selectedDirection===d.id?'<span class="proposal-selected">✓ 已选定</span>':''}</div>`}
export function openProposal({d,i,p,esc,onDevelop,onRefine}){
 const r=proposalMeta(i),visualIndex=d.image==='/assets/b.png'?1:d.image==='/assets/c.png'?2:d.image==='/assets/a.png'?0:i,v=proposalMeta(visualIndex),sample=p.brand==='NOMA',image=esc(d.image),brand=esc(p.brand||'品牌'),palette=(d.palette||[]).filter(c=>/^#[0-9a-f]{3,8}$/i.test(c));
 const dialog=document.createElement('dialog');dialog.className='proposal-dialog route-'+visualIndex;dialog.setAttribute('aria-labelledby','proposal-title');
 dialog.innerHTML=`<div class="proposal-top"><span>创意提案 / 0${i+1}</span><span>方向示意 · 非最终素材</span><button data-close aria-label="关闭提案">关闭 ×</button></div><div class="proposal-scroll"><div class="proposal-heading"><div><div class="eyebrow">${brand} / ${esc(r.role)}</div><h1 id="proposal-title">${esc(d.name)}</h1><p>${esc(d.concept)}</p></div><div class="proposal-intent"><span class="label">希望被记住的事</span><h3>${esc(r.thesis)}</h3></div></div><div class="proposal-brief"><span>本次共同目标</span><p>${esc(p.objective||p.goal||"确认品牌表达，探索推广方向")}</p><span>面向谁</span><p>${esc(p.audience||p.brief?.audience||"受众待确认")}</p></div><div class="proposal-board"><figure class="proposal-hero"><img src="${image}" alt="${esc(d.visualDirection)}"><figcaption>01 / 主视觉气氛<span>${esc(v.note)}</span></figcaption></figure><div class="proposal-side"><div class="type-study"><span class="label">02 / 字体与文案关系</span><strong>${esc(d.keyMessage)}</strong><small>${esc(v.layout)}</small></div><div class="color-study"><span class="label">03 / 色彩节奏</span><div>${palette.map(c=>`<span style="background:${c}"></span>`).join('')}</div><small>${esc(d.visualDirection)}</small></div>${sample?`<figure class="material-study"><img src="/assets/material-detail.png" alt="NOMA 产品材质近景"><figcaption>04 / 产品识别锚点 · 材质与结构</figcaption></figure>`:`<div class="proposal-product-note"><span class="label">04 / 产品识别锚点</span><p>延展时保留产品轮廓、品牌标识与关键卖点。</p></div>`}</div></div><div class="proposal-reason"><div><span class="label">为什么这样表达 · 提案假设</span><p>${esc(r.reason)}</p></div><div><span class="label">已有创意线索</span><p>${esc(d.builtFrom||d.visualDirection)}</p>${d.feedback?`<small>最近调整：${esc(d.feedback)}</small>`:''}</div></div><div class="application-heading"><div><span class="eyebrow">从方向到使用场景</span><h2>放到真实版面里，再判断一次。</h2></div><span>版式预演 / 使用现有示例图</span></div><div class="proposal-applications"><figure><div class="social-preview"><img src="${image}" alt="社交封面版式示意"><div><small>${brand} / 日常灵感</small><strong>${esc(d.keyMessage)}</strong></div></div><figcaption>社交封面 · 用一句主张建立第一印象</figcaption></figure><figure><div class="shop-preview"><div class="shop-nav">${brand}<span>产品故事 / 设计细节</span></div><div class="shop-content"><div><small>${esc(p.product||'产品系列')}</small><h3>${esc(d.keyMessage)}</h3><span class="mock-link">探索产品 ↗</span></div><img src="${image}" alt="产品页首屏版式示意"></div></div><figcaption>产品页首屏 · 从品牌情绪进入产品介绍</figcaption></figure></div><div class="proposal-evaluation"><div><span class="label">适合什么</span><p>${esc(r.strength)}</p></div><div><span class="label">需要权衡</span><p>${esc(r.tradeoff)}</p></div><div><span class="label">这次请判断</span><p>这是不是你希望品牌给人的感觉？想保留哪些元素，调整哪些部分？</p></div></div><p class="proposal-disclaimer">演示提案：视觉与版式用于讨论方向；创意依据为初步假设，尚未验证传播效果。</p></div><div class="proposal-bottom"><span>先确认方向，再展开完整素材。</span><div><button data-adjust>在对话中调整</button><button class="primary" data-confirm>用这个方向生成素材 ↗</button></div></div>`;
 document.body.append(dialog);const close=()=>dialog.close();dialog.querySelector('[data-close]').onclick=close;dialog.querySelector('[data-adjust]').onclick=()=>{close();onRefine(d.id)};dialog.querySelector('[data-confirm]').onclick=()=>{close();onDevelop(d.id)};dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();return close;
}
